    private val call = CallOptions(
        prompt = listOf(ModelMessage.User(listOf(UserPart.Text("what is 12 + 7, times 3, times 10?")))),
        tools = listOf(Tool.Function("calculator", buildJsonObject { put("type", "object") })),
    )

    @Test
    fun `the recorded stream yields the payload OpenAI expects back, not the one it announced`() = runTest {
        val server = TestServer(TestServer.sse(*streamed.toTypedArray()))
        val model = OpenAIResponsesLanguageModel(modelId = "gpt-5.1-codex-max", http = server.http())

        val result = assembleGenerateResult(model.doStream(call).stream)

        val reasoning = result.content.filterIsInstance<Content.Reasoning>().single()
        assertEquals("**Calculating step-by-step using calculator**\n\nI'll compute 12 plus 7, then multiply the result by 3, and finally multiply that by 10, reporting the final product.", reasoning.text)

        val openai = reasoning.providerMetadata?.get(OPENAI_PROVIDER_ID)
        assertEquals("rs_01830d662ab3856501693c321405c88190be3ab04d5782d5f9", openai?.get(OPENAI_ITEM_ID_KEY).string())
        assertEquals(ENCRYPTED_ON_DONE, openai?.get(OPENAI_ENCRYPTED_REASONING_KEY).string())
        assertNotEquals(
            ENCRYPTED_ON_ADDED,
            openai?.get(OPENAI_ENCRYPTED_REASONING_KEY).string(),
            "the announced payload is not the one OpenAI takes back; replaying it wastes the round",
        )

        val toolCall = result.content.filterIsInstance<Content.ToolCall>().single()
        assertEquals("call_AB6AaRZ1FYZB2RwS6A5vbdqn", toolCall.toolCallId)
        assertEquals("calculator", toolCall.toolName)
        assertEquals("""{"a":12,"b":7,"op":"add"}""", toolCall.input)

        // The API says nothing at all about a normal finish; a pending call is what makes it tool-calls.
        assertEquals(FinishReason.Unified.ToolCalls, result.finishReason.unified)
        assertEquals(134, result.usage.inputTokens.total)
        assertEquals(28, result.usage.outputTokens.total)
        assertEquals("resp_01830d662ab3856501693c321345c88190b0de00f3b9975691", result.response?.metadata?.id)
        assertEquals("gpt-5.1-codex-max", result.response?.metadata?.modelId)
        // `created_at` is epoch SECONDS on the wire and epoch millis in the spec.
        assertEquals(1765552659000L, result.response?.metadata?.timestamp)
    }

    @Test
    fun `the recorded non-streaming body carries the same reasoning payload`() = runTest {
        val server = TestServer(TestServer.json(recordedResponse))
        val model = OpenAIResponsesLanguageModel(modelId = "gpt-5-mini", http = server.http())

        val result = model.doGenerate(call)

        val reasoning = result.content.filterIsInstance<Content.Reasoning>().single()
        val openai = reasoning.providerMetadata?.get(OPENAI_PROVIDER_ID)
        assertEquals("rs_0f35ed53160b395301693cc95817ac8190b978637daea4987e", openai?.get(OPENAI_ITEM_ID_KEY).string())
        assertEquals(JSON_ENCRYPTED, openai?.get(OPENAI_ENCRYPTED_REASONING_KEY).string())

        assertEquals("12 + 7 = 19\n19 × 3 = 57\n57 × 10 = 570\n\nFinal result: 570", result.content.filterIsInstance<Content.Text>().single().text)
        assertEquals(FinishReason.Unified.Stop, result.finishReason.unified)
    }

